// generar_293_vet_resumen_semaforo_y_compactar.js
// CHIQUI Entre Señales — Vista veterinaria: más compacta y mejor organizada
//
// Cambios pedidos + limpieza visual para que no se vea tan largo:
//
// 1) FICHA DEL PACIENTE
//    · Tamaño ahora dice solo "Mediano" (sin el rango "(10–25 kg)").
//    · Se quita "Veterinaria habitual".
//
// 2) RESUMEN CLÍNICO
//    · Título en negrita (📋 Resumen clínico).
//    · La info se AGRUPA POR SEMÁFORO, con encabezado y punto de color:
//        🔴 Requiere atención  → vacunas/antiparasitario vencidos,
//                                parámetros fuera de rango.
//        🟡 A observar         → cambios de peso, observaciones activas.
//        🟢 Al día             → vacunas al día, antiparasitario vigente,
//                                fechas de últimos exámenes.
//      Rojo primero, luego amarillo, luego verde: lo importante arriba.
//
// 3) POSIBLE MOTIVO DE CONSULTA
//    · La dieta especial deja de tener cuadro propio y aparece como un
//      chip más aquí (ej. "Dieta blanda · 1 día"), junto a los demás
//      motivos. Misma naturaleza de información, menos scroll.
//
// 4) ACTIVIDAD FÍSICA
//    · Ahora es DESPLEGABLE (como el resto del historial). El promedio
//      diario y el nivel (Activo/Moderado/Bajo) quedan en el título, así
//      que se ve el dato clave sin abrir, y el detalle al tocar.
//
// Resultado: la parte de arriba de la vista del vet es bastante más
// corta y se escanea más rápido, sin perder información.
//
// No hay SQL.
//
// Uso:
//   node generar_293_vet_resumen_semaforo_y_compactar.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/vet/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
